CREATE TABLE IF NOT EXISTS edu_assessment_scheme (id varchar(64) PRIMARY KEY,create_by varchar(128) NOT NULL,create_time timestamp NOT NULL,last_update_by varchar(128),last_update_time timestamp,school_id varchar(64) NOT NULL,offering_id varchar(64) NOT NULL,name varchar(200) NOT NULL,total_score numeric(8,2) NOT NULL,pass_score numeric(8,2) NOT NULL,status varchar(24) NOT NULL DEFAULT 'DRAFT',published_version_no integer,row_version bigint NOT NULL DEFAULT 0,CONSTRAINT ck_edu_scheme_score CHECK(total_score>0 AND pass_score>=0 AND pass_score<=total_score));
CREATE TABLE IF NOT EXISTS edu_assessment_component (id varchar(64) PRIMARY KEY,create_by varchar(128) NOT NULL,create_time timestamp NOT NULL,last_update_by varchar(128),last_update_time timestamp,scheme_id varchar(64) NOT NULL,code varchar(64) NOT NULL,name varchar(200) NOT NULL,source_type varchar(16) NOT NULL,max_score numeric(8,2) NOT NULL,weight numeric(8,2) NOT NULL,sort_order integer NOT NULL DEFAULT 0,CONSTRAINT uk_edu_assessment_component_code UNIQUE(scheme_id,code),CONSTRAINT ck_edu_assessment_component_source CHECK(source_type IN('MANUAL')),CONSTRAINT ck_edu_assessment_component_weight CHECK(weight>0));
CREATE TABLE IF NOT EXISTS edu_gradebook (id varchar(64) PRIMARY KEY,create_by varchar(128) NOT NULL,create_time timestamp NOT NULL,last_update_by varchar(128),last_update_time timestamp,school_id varchar(64) NOT NULL,offering_id varchar(64) NOT NULL,scheme_id varchar(64) NOT NULL,teacher_id varchar(64) NOT NULL,status varchar(24) NOT NULL DEFAULT 'DRAFT',submission_no integer NOT NULL DEFAULT 0,workflow_instance_id varchar(64),submitted_at timestamp,published_at timestamp,row_version bigint NOT NULL DEFAULT 0,CONSTRAINT uk_edu_gradebook_active_offering_scheme UNIQUE(offering_id,scheme_id));
CREATE TABLE IF NOT EXISTS edu_gradebook_student (id varchar(64) PRIMARY KEY,create_by varchar(128) NOT NULL,create_time timestamp NOT NULL,last_update_by varchar(128),last_update_time timestamp,gradebook_id varchar(64) NOT NULL,student_id varchar(64) NOT NULL,student_no varchar(64) NOT NULL,student_name varchar(128) NOT NULL,administrative_class_id varchar(64),enrollment_status varchar(24) NOT NULL,source_member_id varchar(64) NOT NULL,enrolled_at timestamp,withdrawn_at timestamp,snapshot_version integer NOT NULL DEFAULT 1,snapshot_hash varchar(64) NOT NULL,CONSTRAINT uk_edu_gradebook_student UNIQUE(gradebook_id,student_id));
CREATE TABLE IF NOT EXISTS edu_grade_item (id varchar(64) PRIMARY KEY,create_by varchar(128) NOT NULL,create_time timestamp NOT NULL,last_update_by varchar(128),last_update_time timestamp,gradebook_id varchar(64) NOT NULL,component_id varchar(64) NOT NULL,student_id varchar(64) NOT NULL,raw_score numeric(8,2),converted_score numeric(8,2),special_status varchar(24),remark varchar(500),row_version bigint NOT NULL DEFAULT 0,CONSTRAINT uk_edu_grade_item UNIQUE(gradebook_id,component_id,student_id));
CREATE TABLE IF NOT EXISTS edu_course_grade (id varchar(64) PRIMARY KEY,create_by varchar(128) NOT NULL,create_time timestamp NOT NULL,last_update_by varchar(128),last_update_time timestamp,gradebook_id varchar(64) NOT NULL,student_id varchar(64) NOT NULL,total_score numeric(8,2) NOT NULL,grade_level varchar(16),grade_point numeric(5,2),passed boolean NOT NULL,version_no integer NOT NULL,snapshot_hash varchar(64) NOT NULL,CONSTRAINT uk_edu_course_grade_version UNIQUE(gradebook_id,student_id,version_no));
CREATE TABLE IF NOT EXISTS edu_grade_publish_snapshot (id varchar(64) PRIMARY KEY,create_by varchar(128) NOT NULL,create_time timestamp NOT NULL,last_update_by varchar(128),last_update_time timestamp,gradebook_id varchar(64) NOT NULL,version_no integer NOT NULL,snapshot_json text NOT NULL,published_by varchar(128) NOT NULL,published_at timestamp NOT NULL,snapshot_hash varchar(64) NOT NULL,CONSTRAINT uk_edu_grade_publish_snapshot UNIQUE(gradebook_id,version_no));
CREATE INDEX IF NOT EXISTS idx_edu_gradebook_student_student ON edu_gradebook_student(student_id); CREATE INDEX IF NOT EXISTS idx_edu_gradebook_status ON edu_gradebook(status);
